using ChroniclesLauncher.Updates;
static class LeaseChecks {
 public static void Run(string scratch){var app=Path.Combine(scratch,"sample.app");var bin=Path.Combine(app,"Contents","MacOS");Directory.CreateDirectory(bin);if(InstallationLease.CanonicalRoot(bin+Path.DirectorySeparatorChar)!=InstallationLease.CanonicalRoot(app))throw new Exception("Trailing separator changed installation identity");var root=Path.Combine(scratch,"lease-install");Directory.CreateDirectory(root);using(var first=InstallationLease.TryAcquire(root)??throw new Exception("First lease failed")){using var second=InstallationLease.TryAcquire(root);if(second!=null)throw new Exception("Concurrent lease granted");}using var third=InstallationLease.TryAcquire(root)??throw new Exception("Lease not released");Console.WriteLine("PASS Installation lease rejects overlap and releases on disposal");}
}
